package pzvrphysicality;

import java.util.*;import local.pzvr.VrApi;import zombie.characters.IsoPlayer;import zombie.inventory.InventoryItem;import zombie.inventory.types.InventoryContainer;

/** Only publishes native worn-back and hotbar actions. Native Lua actions retain all item ownership. */
public final class NativeBody {
 public record Slot(String id,int zone,InventoryItem item,String location,boolean left,boolean right){}
 public record Request(int kind,int side,IsoPlayer actor,InventoryItem item,String slot,long ticket,long epoch,long rigGeneration,long created){}
 private static final BodyPolicy policy=new BodyPolicy();private static final List<Slot> slots=new ArrayList<>();
 private static volatile BodyRig rig;private static volatile boolean enabled;private static double radius=.16;
 private static final double[][] offsets={{-.22,0,-.80},{.22,0,-.80},{.10,-.16,-.25}};
 private static IsoPlayer actor;private static Request pending,active;private static long epoch=1,sequence,slotTime,rigGeneration=-1;private static String status="Body storage Off";
 public static void configure(boolean value,double radiusCm){double r=Math.clamp(radiusCm/100,.06,.22);if(!Double.isFinite(radiusCm))throw new IllegalArgumentException("Body reach");if(enabled!=value||r!=radius){enabled=value;radius=r;reset();}WorldRigCapture.requestBody(value);status=value?"Reach to a native hotbar item or over a shoulder; release there to store":"Body storage Off";}
 public static void anchor(int zone,double x,double y,double z){if(zone<0||zone>2||!Double.isFinite(x)||!Double.isFinite(y)||!Double.isFinite(z)||Math.abs(x)>.6||Math.abs(y)>.6||z< -1.4||z>-.05)throw new IllegalArgumentException("Body anchor");if(offsets[zone][0]!=x||offsets[zone][1]!=y||offsets[zone][2]!=z){offsets[zone]=new double[]{x,y,z};reset();}}
 private static void reset(){pending=active=null;actor=null;slots.clear();slotTime=0;rig=null;rigGeneration=-1;epoch++;policy.reset();BodyAnchorCapture.clear();}
 public static boolean enabled(){return enabled;}
 public static String status(){return status+"; "+slots.size()+" native hotbar slots";}
 private static IsoPlayer player(){return IsoPlayer.players.length==0?null:IsoPlayer.players[0];}
 private static boolean ownAction(IsoPlayer p,long ticket){if(!p.hasTimedActions())return true;var actions=p.getCharacterActions();if(actions==null||actions.isEmpty()||!(actions.getFirst() instanceof zombie.characters.CharacterTimedActions.LuaTimedActionNew action)||action.getTable()==null)return false;Object value=action.getTable().rawget("pzvrBodyTicket");return value instanceof Number number&&number.doubleValue()==ticket;}
 public static boolean context(IsoPlayer p,long generation){long now=System.nanoTime();var r=WorldRigCapture.body;rig=r;return enabled&&generation==epoch&&Main.ready()&&p!=null&&p==player()&&!p.isDead()&&p.getVehicle()==null&&p.getSquare()!=null&&!zombie.network.GameClient.client&&!zombie.network.GameServer.server&&!zombie.GameTime.isGamePaused()&&!VrApi.fullHud()&&!VrApi.pointerActive()&&!zombie.ui.UIManager.isModalVisible()&&!zombie.core.Core.getInstance().isDoingTextEntry()&&(active!=null?ownAction(p,active.ticket()):!p.hasTimedActions()&&(pending!=null||NativeItems.request()==null&&NativeItems.supportsPhysicalGestures(p)))&&r!=null&&r.rig().actor()==p&&r.rig().fresh(now)&&WorldRigCapture.latest==r.rig()&&PzvrContacts.sample(now)!=null;}
 public static void begin(IsoPlayer p){if(p!=actor){reset();actor=p;}slots.clear();slotTime=System.nanoTime();}
 public static void slot(String id,int zone,InventoryItem item,String location,boolean left,boolean right){if(enabled&&slots.size()<24&&id!=null&&id.length()<=96&&zone>=0&&zone<=2&&slots.stream().noneMatch(s->s.id().equals(id)))slots.add(new Slot(id,zone,item,location,left,right));}
 private static boolean owns(IsoPlayer p,InventoryItem item){return item!=null&&item.getContainer()==p.getInventory()&&p.getInventory().contains(item)&&item.getWorldItem()==null;}
 private static boolean supported(InventoryItem item){return item!=null&&!item.isForceDropHeavyItem()&&!item.isRequiresEquippedBothHands()&&!item.hasTag(zombie.scripting.objects.ItemTag.REPLACE_PRIMARY);}
 private static boolean wearable(InventoryItem item){return item instanceof InventoryContainer bag&&supported(item)&&!item.isBroken()&&bag.canBeEquipped()==zombie.scripting.objects.ItemBodyLocation.BACK;}
 private static ContactFrame.Point at(Slot slot){var r=rig;if(r==null)return null;var actual=BodyAnchorCapture.point(r.rig(),slot.location());if(actual!=null)return actual;var o=offsets[slot.zone()];return r.at(o[0],o[1],o[2]);}
 private static double shoulder(int side,ContactFrame.Point hand){var r=rig;if(r==null||hand==null)return Double.POSITIVE_INFINITY;var o=offsets[2];return hand.distance(r.at(side==0?-Math.abs(o[0]):Math.abs(o[0]),o[1],o[2]))/r.units();}
 private static Slot nearest(int side,ContactFrame.Point point,boolean store){if(point==null||rig==null||System.nanoTime()-slotTime>150_000_000L)return null;var p=player();Slot result=null;double best=radius*rig.units();for(var s:slots){var item=NativeItems.hand(p,side);if(store?(s.item()!=null||!supported(item)||!(side==0?s.left():s.right())):(!supported(s.item())||item!=null||!owns(p,s.item())||NativeItems.hand(p,1-side)==s.item()))continue;var at=at(s);if(at==null)continue;double d=point.distance(at);if(d<best){best=d;result=s;}}return result;}
 public static boolean ownsGrip(int side){if(side<0||side>1||!enabled)return false;var p=player();if(!context(p,epoch))return false;if(active!=null&&active.side()==side||pending!=null&&pending.side()==side)return true;var other=NativeItems.hand(p,1-side);if(other!=null&&!supported(other))return false;var contact=PzvrContacts.sample(System.nanoTime());var h=contact==null?null:contact.hand(side);if(h==null)return false;var held=NativeItems.hand(p,side);return nearest(side,h.centre(),held!=null)!=null||shoulder(side,h.centre())<=radius&&(held==null&&wearable(p.getClothingItem_Back())||wearable(held)&&p.getClothingItem_Back()==null);}
 public static void tick(){if(!enabled)return;var p=player();long now=System.nanoTime();if(p!=actor){reset();actor=p;}if(pending!=null&&now-pending.created()>250_000_000L)pending=null;if(active!=null&&now-active.created()>15_000_000_000L){active=null;policy.reset();}var contacts=PzvrContacts.sample(now);boolean allowed=context(p,epoch);if(!allowed||contacts==null){pending=active=null;policy.reset();return;}if(rigGeneration!=rig.rig().generation()){pending=active=null;policy.reset();epoch++;rigGeneration=rig.rig().generation();}if(pending!=null||active!=null||p.hasTimedActions())return;
  for(int side=0;side<2;side++){var h=contacts.hand(side);var e=policy.sample(side,h!=null&&h.grip(),h!=null);if(h==null||e==BodyPolicy.Edge.NONE)continue;var other=NativeItems.hand(p,1-side);if(other!=null&&!supported(other))continue;var held=NativeItems.hand(p,side);InventoryItem item=null;int kind=0;String slot="";
   if(shoulder(side,h.centre())<=radius){if(e==BodyPolicy.Edge.DRAW&&held==null&&wearable(p.getClothingItem_Back())&&owns(p,p.getClothingItem_Back())){kind=1;item=p.getClothingItem_Back();}else if(e==BodyPolicy.Edge.STORE&&wearable(held)&&p.getClothingItem_Back()==null&&owns(p,held)){kind=2;item=held;}}
   if(kind==0){var target=nearest(side,h.centre(),e==BodyPolicy.Edge.STORE);if(target!=null){kind=e==BodyPolicy.Edge.DRAW?3:4;item=kind==3?target.item():held;slot=target.id();}}
   if(kind!=0){pending=new Request(kind,side,p,item,slot,++sequence,epoch,rig.rig().generation(),now);status="Native body action selected";break;}
  }
 }
 public static Request request(){return pending;}
 public static boolean valid(IsoPlayer p,InventoryItem item,int side,long ticket,long generation){var r=active!=null?active:pending;long now=System.nanoTime();var contacts=PzvrContacts.sample(now);var h=contacts==null||side<0||side>1?null:contacts.hand(side);return r!=null&&now>=r.created()&&now-r.created()<(active!=null?15_000_000_000L:250_000_000L)&&r.actor()==p&&r.item()==item&&r.side()==side&&r.ticket()==ticket&&r.epoch()==generation&&context(p,generation)&&rig.rig().generation()==r.rigGeneration()&&owns(p,item)&&rig.rig().hand(side)!=null&&((r.kind()!=1&&r.kind()!=3)||h!=null&&h.grip());}
 public static boolean acknowledge(long ticket,boolean queued){if(pending==null||pending.ticket()!=ticket)return false;var r=pending;pending=null;if(queued&&validRequest(r)){active=r;return true;}policy.reset();return false;}
 private static boolean validRequest(Request r){long now=System.nanoTime();return now>=r.created()&&now-r.created()<250_000_000L&&context(r.actor(),r.epoch())&&owns(r.actor(),r.item())&&rig.rig().generation()==r.rigGeneration();}
 public static void finished(long ticket,boolean received){var r=active;if(r==null||r.ticket()!=ticket)return;if(received&&valid(r.actor(),r.item(),r.side(),r.ticket(),r.epoch())&&NativeItems.hand(r.actor(),r.side())==r.item())NativeItems.adoptBody(r.actor(),r.item(),r.side());active=null;status=received?"Original item drawn from body storage":"Native body action finished";}
 public static double calibration(int side,int axis){var p=player();var input=local.pzvr.Engine.latestInput;long now=System.nanoTime();var contacts=PzvrContacts.sample(now);if(side<0||side>1||axis<0||axis>2||!enabled||p==null||p.isDead()||p.getVehicle()!=null||p.hasTimedActions()||zombie.network.GameClient.client||zombie.network.GameServer.server||input==null||input.head()==null||contacts==null||contacts.hand(side)==null)return Double.NaN;var h=side==0?input.left():input.right();if(h==null||!h.tracked()||h.grip()==null)return Double.NaN;var head=input.head();var right=head.rotation().rotate(new local.pzvr.Math3.Vec(1,0,0));var forward=head.rotation().rotate(new local.pzvr.Math3.Vec(0,0,-1));double length=Math.hypot(right.x(),right.z());if(length<.1)return Double.NaN;double rx=right.x()/length,rz=right.z()/length,fx=-rz,fz=rx;if(fx*forward.x()+fz*forward.z()<0){fx=-fx;fz=-fz;}var point=h.grip().position();var origin=head.position();double x=point.x()-origin.x(),y=point.z()-origin.z();double[] result={x*rx+y*rz,x*fx+y*fz,point.y()-origin.y()};return input==local.pzvr.Engine.latestInput?result[axis]:Double.NaN;}
 private NativeBody(){}
}
